WITH scored AS (SELECT *, LAST_VALUE(quantity, TRUE) OVER (ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity, LEAD(quantity, 1) OVER (PARTITION BY product_id ORDER BY last_restock, id) AS next_quantity FROM inventory) SELECT product_id, MAX(last_known_quantity) AS max_last_known_quantity, ROUND(AVG(last_known_quantity), 2) AS avg_last_known_quantity, ROUND(AVG(quantity), 2) AS avg_quantity FROM scored GROUP BY 1 HAVING MAX(last_known_quantity) < 0 ORDER BY product_id;
